import React, { useState, useEffect } from 'react';

function AuthScreen({ users, onLogin, onRegister, onForgotPassword, onBack, mode, onSwitchMode, statusMessage }) {
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [confirmPassword, setConfirmPassword] = useState('');

  useEffect(() => {
    setEmail('');
    setPassword('');
    setConfirmPassword('');
  }, [mode]);

  const handleSubmit = (e) => {
    e.preventDefault();

    if (mode === 'login') {
      const user = users.find((u) => u.email === email && u.password === password);
      if (user) {
        onLogin(user);
        return;
      }
      alert('Email hoặc mật khẩu không đúng. Vui lòng thử lại.');
      return;
    }

    if (mode === 'register') {
      if (password !== confirmPassword) {
        alert('Mật khẩu và xác nhận mật khẩu phải giống nhau.');
        return;
      }
      const success = onRegister({ email, password, username: email.split('@')[0] });
      if (success) {
        return;
      }
      return;
    }

    if (mode === 'forgot') {
      const success = onForgotPassword(email);
      if (success) {
        return;
      }
      return;
    }
  };

  return (
    <div>
      <button className="btn mb-4 fw-bold text-white border-0" style={{ background: 'linear-gradient(135deg, #7c3aed 0%, #a855f7 100%)' }} onClick={onBack}>⬅ Quay lại trang chủ</button>
      <div className="card p-4 shadow border-0 mx-auto bg-white" style={{ maxWidth: '420px', borderRadius: '20px', backgroundColor: '#faf5ff' }}>
        <div className="d-flex justify-content-between align-items-center mb-4">
          <h3 className="text-center fw-bold mb-0" style={{ color: '#7c3aed' }}>
            {mode === 'login' && 'ĐĂNG NHẬP'}
            {mode === 'register' && 'ĐĂNG KÝ'}
            {mode === 'forgot' && 'QUÊN MẬT KHẨU'}
          </h3>
        </div>

        {statusMessage && (
          <div className="alert alert-info py-2 px-3 mb-3" style={{ borderRadius: '14px' }}>
            {statusMessage}
          </div>
        )}

        <form onSubmit={handleSubmit}>
          <div className="mb-3">
            <label className="form-label fw-bold small" style={{ color: '#6b7280' }}>Địa chỉ Email</label>
            <input
              type="email"
              className="form-control py-2"
              style={{ borderRadius: '12px', border: '1px solid #e5e7eb' }}
              placeholder="name@example.com"
              value={email}
              onChange={(e) => setEmail(e.target.value)}
              required
            />
          </div>

          {mode !== 'forgot' && (
            <div className="mb-3">
              <label className="form-label fw-bold small" style={{ color: '#6b7280' }}>Mật khẩu</label>
              <input
                type="password"
                className="form-control py-2"
                style={{ borderRadius: '12px', border: '1px solid #e5e7eb' }}
                placeholder="••••••••"
                value={password}
                onChange={(e) => setPassword(e.target.value)}
                required
              />
            </div>
          )}

          {mode === 'register' && (
            <div className="mb-3">
              <label className="form-label fw-bold small" style={{ color: '#6b7280' }}>Xác nhận mật khẩu</label>
              <input
                type="password"
                className="form-control py-2"
                style={{ borderRadius: '12px', border: '1px solid #e5e7eb' }}
                placeholder="••••••••"
                value={confirmPassword}
                onChange={(e) => setConfirmPassword(e.target.value)}
                required
              />
            </div>
          )}

          <button type="submit" className="btn w-100 fw-bold mt-3 py-2 text-white border-0" style={{ background: 'linear-gradient(135deg, #7c3aed 0%, #a855f7 100%)' }}>
            {mode === 'login' && 'ĐĂNG NHẬP'}
            {mode === 'register' && 'ĐĂNG KÝ'}
            {mode === 'forgot' && 'GỬI YÊU CẦU'}
          </button>
        </form>

        <div className="text-center mt-4">
          {mode === 'login' && (
            <button className="btn btn-link text-decoration-none" onClick={() => onSwitchMode('forgot')}>Quên mật khẩu?</button>
          )}
          {mode !== 'login' && (
            <button className="btn btn-link text-decoration-none" onClick={() => onSwitchMode('login')}>Quay lại đăng nhập</button>
          )}
        </div>

        <div className="text-center mt-3">
          {mode !== 'register' && (
            <button className="btn btn-link text-decoration-none" onClick={() => onSwitchMode('register')}>Chưa có tài khoản? Đăng ký ngay</button>
          )}
        </div>
      </div>
    </div>
  );
}

export default AuthScreen;
